80	/// Runs memory phase 1 in strict step order:
81	/// 1) claim eligible rollout jobs
82	/// 2) build one stage-1 request context
83	/// 3) run stage-1 extraction jobs in parallel
84	/// 4) emit metrics and logs
85	pub(in crate::memories) async fn run(session: &Arc<Session>, config: &Config) {
86	    let _phase_one_e2e_timer = session
87	        .services
88	        .session_telemetry
89	        .start_timer(metrics::MEMORY_PHASE_ONE_E2E_MS, &[])
90	        .ok();
91	
92	    // 1. Claim startup job.
93	    let Some(claimed_candidates) = claim_startup_jobs(session, &config.memories).await else {
94	        return;
95	    };
96	    if claimed_candidates.is_empty() {
97	        session.services.session_telemetry.counter(
98	            metrics::MEMORY_PHASE_ONE_JOBS,
99	            1,
100	            &[("status", "skipped_no_candidates")],
101	        );
102	        return;
103	    }
104	
105	    // 2. Build request.
106	    let stage_one_context = build_request_context(session, config).await;
107	
108	    // 3. Run the parallel sampling.
109	    let outcomes = run_jobs(session, claimed_candidates, stage_one_context).await;
110	
111	    // 4. Metrics and logs.
112	    let counts = aggregate_stats(outcomes);
113	    emit_metrics(session, &counts);
114	    info!(
115	        "memory stage-1 extraction complete: {} job(s) claimed, {} succeeded ({} with output, {} no output), {} failed",
116	        counts.claimed,
117	        counts.succeeded_with_output + counts.succeeded_no_output,
118	        counts.succeeded_with_output,
119	        counts.succeeded_no_output,
120	        counts.failed
121	    );
122	}
