124	/// Prune old un-used "dead" raw memories.
125	pub(in crate::memories) async fn prune(session: &Arc<Session>, config: &Config) {
126	    if let Some(db) = session.services.state_db.as_deref() {
127	        let max_unused_days = config.memories.max_unused_days;
128	        match db
129	            .prune_stage1_outputs_for_retention(max_unused_days, PRUNE_BATCH_SIZE)
130	            .await
131	        {
132	            Ok(pruned) => {
133	                if pruned > 0 {
134	                    info!(
135	                        "memory startup pruned {pruned} stale stage-1 output row(s) older than {max_unused_days} days"
136	                    );
137	                }
138	            }
139	            Err(err) => {
140	                warn!(
141	                    "state db prune_stage1_outputs_for_retention failed during memories startup: {err}"
142	                );
143	            }
144	        }
145	    }
146	}
